	if options.ErrorHandlerFunc == nil {
		options.ErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}

	wrapper := ServerInterfaceWrapper{
		Handler:            si,
		HandlerMiddlewares: options.Middlewares,
		ErrorHandlerFunc:   options.ErrorHandlerFunc,
	}

	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/state", wrapper.GetState)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/catalogue", wrapper.GetCatalogue)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/config", wrapper.GetConfig)
	m.HandleFunc(http.MethodPut+" "+options.BaseURL+"/config", wrapper.PutConfig)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/config/reset", wrapper.ResetConfig)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/presets/{name}", wrapper.ApplyPreset)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/pause", wrapper.Pause)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/resume", wrapper.Resume)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/act", wrapper.ActNow)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/history/rebuild", wrapper.RebuildHistory)
