// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {
	// ActNow One persona does one action now
	// (POST /act)
	ActNow(ctx context.Context, request ActNowRequestObject) (ActNowResponseObject, error)
	// GetCatalogue What can be tuned
	// (GET /catalogue)
	GetCatalogue(ctx context.Context, request GetCatalogueRequestObject) (GetCatalogueResponseObject, error)
	// GetConfig The configuration in force
	// (GET /config)
	GetConfig(ctx context.Context, request GetConfigRequestObject) (GetConfigResponseObject, error)
	// PutConfig Replace the configuration
	// (PUT /config)
	PutConfig(ctx context.Context, request PutConfigRequestObject) (PutConfigResponseObject, error)
	// ResetConfig Back to the defaults the simulator started with
	// (POST /config/reset)
	ResetConfig(ctx context.Context, request ResetConfigRequestObject) (ResetConfigResponseObject, error)
	// StreamEvents The actions as they run
	// (GET /events)
	StreamEvents(ctx context.Context, request StreamEventsRequestObject) (StreamEventsResponseObject, error)
	// RebuildHistory Every persona that plays rebuilds its history with the configured profile
	// (POST /history/rebuild)
	RebuildHistory(ctx context.Context, request RebuildHistoryRequestObject) (RebuildHistoryResponseObject, error)
	// Pause Stop every persona after its current action
	// (POST /pause)
	Pause(ctx context.Context, request PauseRequestObject) (PauseResponseObject, error)
	// ApplyPreset Apply a preset to the current configuration
	// (POST /presets/{name})
	ApplyPreset(ctx context.Context, request ApplyPresetRequestObject) (ApplyPresetResponseObject, error)
	// Resume Let the personas go on
	// (POST /resume)
	Resume(ctx context.Context, request ResumeRequestObject) (ResumeResponseObject, error)
	// GetState What runs now
	// (GET /state)
	GetState(ctx context.Context, request GetStateRequestObject) (GetStateResponseObject, error)
}

type StrictHandlerFunc func(ctx context.Context, w http.ResponseWriter, r *http.Request, request any) (any, error)
type StrictMiddlewareFunc func(f StrictHandlerFunc, operationID string) StrictHandlerFunc

type StrictHTTPServerOptions struct {
	RequestErrorHandlerFunc  func(w http.ResponseWriter, r *http.Request, err error)
	ResponseErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

func NewStrictHandler(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: StrictHTTPServerOptions{
		RequestErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		},
		ResponseErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		},
	}}
}

func NewStrictHandlerWithOptions(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc, options StrictHTTPServerOptions) ServerInterface {
	if options.RequestErrorHandlerFunc == nil {
		options.RequestErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}
	if options.ResponseErrorHandlerFunc == nil {
		options.ResponseErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		}
	}
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: options}
}

type strictHandler struct {
	ssi         StrictServerInterface
	middlewares []StrictMiddlewareFunc
	options     StrictHTTPServerOptions
}

